insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('53aa570a-cf95-543b-b744-3e5b7ee44e08', '60a4214d-9a37-56b6-a477-deed35c6d87d', 1, 'Boil the pasta in well-salted water. Reserve a cup of the water before draining.', 'اسلق المكرونة في مية مملّحة كويس. شيل كوباية من ميتها قبل ما تصفّيها.', 10, null, null, '{"pasta"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('f04b52c3-4bb3-5312-87f4-771bcffb2136', '60a4214d-9a37-56b6-a477-deed35c6d87d', 2, 'Season the chicken and sear in butter over high heat until golden on both sides.', 'تبّل الفراخ وشوّحها في الزبدة على نار عالية لحد ما تتحمّر من الناحيتين.', 7, 'Cook chicken until it reaches 74°C / 165°F and no pink remains. Wash hands and the board after handling raw poultry.', 'اطبخ الفراخ لحد ما توصل ٧٤°م / ١٦٥°ف ومايفضلش فيها لون وردي. اغسل إيديك واللوح بعد ما تلمس فراخ نية.', '{"chicken breast","butter","black pepper"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('30c340bc-52de-5033-b313-dc98646f566b', '60a4214d-9a37-56b6-a477-deed35c6d87d', 3, 'Lower the heat, add the garlic for 30 seconds, then pour in the cream and let it bubble for 2 minutes.', 'هدّي النار، ضيف التوم ٣٠ ثانية، وبعدين صبّ الكريمة وسيبها تغلي دقيقتين.', 3, null, null, '{"garlic","cooking cream"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('78af77e4-4be0-5dde-94bf-b78784bf9730', '60a4214d-9a37-56b6-a477-deed35c6d87d', 4, 'Toss in the pasta with a splash of its water and the grated cheese until glossy. Finish with parsley.', 'قلّب المكرونة مع شوية من ميتها والجبنة المبشورة لحد ما تلمع. زيّن بالبقدونس.', 3, null, null, '{"roumy cheese","parsley"}');

