values ('0dd6d903-a72e-57b1-ad36-8e547e553dbf', '675e79fc-ff56-59bf-ac47-9845fde452a7', 2, 'Boil the eggs for 7 minutes for a just-set yolk, then peel under cold water.', 'اسلق البيض ٧ دقايق عشان الصفار يستوي ويفضل طري، وبعدين قشّره تحت مية باردة.', 7, 'Boil eggs for at least 7 minutes so the white is fully set.', 'اسلق البيض ٧ دقايق على الأقل عشان البياض يستوي تمامًا.', '{"eggs"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('fd905e76-2e3c-5c1b-ac70-c60bc04133d4', '675e79fc-ff56-59bf-ac47-9845fde452a7', 3, 'Season the foul with cumin, salt and lemon juice, then pour olive oil generously over the top.', 'تبّل الفول بالكمون والملح وعصير الليمون، وبعدين صبّ زيت الزيتون فوقه بسخاء.', 2, null, null, '{"cumin","lemon","olive oil"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('e0fd02a3-8073-53f9-bfd6-0243026c3eb1', '675e79fc-ff56-59bf-ac47-9845fde452a7', 4, 'Halve the eggs onto the beans, scatter tomato and chilli, and scoop it all up with warm bread.', 'حط البيض مقسوم نصين على الفول، رشّ طماطم وشطة، وكل الحكاية بعيش سخن.', 1, null, null, '{"tomatoes","chili flakes","baladi bread"}');

