insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('3ba040a2-d737-5fc1-8a77-a9a546c474fc', '1630107f-aed3-5532-a60e-1af649a84362', 1, 'Boil the potatoes whole in their skins, peel them hot and rice them.', 'اسلق البطاطس صحيحة بقشرها، قشّرها وهي سخنة واهرسها ناعم.', 30, null, null, '{"potatoes"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('e602cd74-3dac-5932-9cda-247ac0ea6f08', '1630107f-aed3-5532-a60e-1af649a84362', 2, 'Work in the flour, yolk and salt with the lightest hand you can — overworking makes them heavy.', 'ادخل الدقيق والصفار والملح بأخف إيد ممكنة — العجن الزيادة بيتقّلهم.', 10, null, null, '{"flour","egg yolks","salt"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('16699534-4d5d-5fce-9d15-af179b362c8a', '1630107f-aed3-5532-a60e-1af649a84362', 3, 'Roll into ropes, cut into pieces, and boil until they float, about 2 minutes.', 'لفّها حبال، قطّعها قطع، واسلقها لحد ما تطفو، حوالي دقيقتين.', 8, null, null, '{}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('965c80fe-a853-5129-8a38-27302732ede2', '1630107f-aed3-5532-a60e-1af649a84362', 4, 'Brown the butter until it smells nutty and toss the gnocchi through it with cheese.', 'حمّر الزبدة لحد ما ريحتها تبقى زي المكسرات وقلّب النيوكي فيها مع الجبنة.', 6, null, null, '{"butter","parmesan","black pepper"}');

