values ('d38c7a39-ccba-51c7-8ac8-3ad64d300ed5', '2b36172e-6022-5dbe-99c1-cb90231c8853', 1, 'Soak the bulgur 30 minutes, squeeze dry, then knead with half the lamb and half the spice until it holds.', 'انقع البرغل ٣٠ دقيقة، اعصره، وبعدين اعجنه مع نص اللحمة ونص البهارات لحد ما يتماسك.', 20, null, null, '{"bulgur","lamb","mixed spice"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('12b41697-1a55-5dcf-a0f8-fc1892bd4d83', '2b36172e-6022-5dbe-99c1-cb90231c8853', 2, 'Fry the onions, add the rest of the lamb, the pine nuts and cinnamon, and cook through.', 'حمّر البصل، ضيف باقي اللحمة والصنوبر والقرفة، واطبخهم لحد ما يستووا.', 12, null, null, '{"onions","pine nuts","cinnamon","salt","black pepper"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('bdb6647b-3063-58d6-9e7f-620b1d50fcc2', '2b36172e-6022-5dbe-99c1-cb90231c8853', 3, 'Press half the bulgur into a greased tray, spread the filling, then top with the rest.', 'اضغط نص البرغل في صينية مدهونة، افرد الحشو، وبعدين غطّيه بالباقي.', 10, null, null, '{"ghee"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('b12b69d8-f1b2-5876-a116-9fb82c6eb5f2', '2b36172e-6022-5dbe-99c1-cb90231c8853', 4, 'Score into diamonds, pour over the ghee and bake at 200°C for 45 minutes.', 'خطّطها معيّنات، صبّ السمنة فوقها واخبزها على ٢٠٠ درجة ٤٥ دقيقة.', 45, 'Lamb mince must be cooked through to 71°C / 160°F.', 'اللحمة الضاني المفرومة لازم تستوي لحد ٧١°م / ١٦٠°ف.', '{}');

