values ('54776632-4d61-5e8d-a669-d5405eecbe32', 'f98c4c9e-21d9-5442-959a-d1052eb5f04b', 1, 'Break the baked pastry into a deep dish and scatter the nuts, coconut and raisins through it.', 'فتّت العجين المخبوز في طبق عميق ووزّع المكسرات وجوز الهند والزبيب فوقه.', 5, null, null, '{"puff pastry","almonds","desiccated coconut","raisins"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('353237d5-2206-5d9f-9aee-c5963d83f8e9', 'f98c4c9e-21d9-5442-959a-d1052eb5f04b', 2, 'Heat the milk with the sugar until steaming, then pour it over and press everything down.', 'سخّن اللبن مع السكر لحد ما يبخّر، وبعدين صبّه فوق واضغط كل حاجة تحت.', 6, null, null, '{"milk","sugar"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('61b7def7-0b2a-5b67-bb5e-2ee0749463b7', 'f98c4c9e-21d9-5442-959a-d1052eb5f04b', 3, 'Spoon the cream over the top and bake at 200°C for 20 minutes until golden and bubbling.', 'وزّع الكريمة فوق واخبزه على ٢٠٠ درجة ٢٠ دقيقة لحد ما يدهب ويفور.', 20, null, null, '{"cooking cream"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('85eb063d-199a-58cf-b938-743440388199', 'f98c4c9e-21d9-5442-959a-d1052eb5f04b', 4, 'Rest 5 minutes before serving — the milk is molten straight out of the oven.', 'سيبه ٥ دقايق قبل التقديم — اللبن بيكون مغلي وهو طالع من الفرن.', 5, 'Let it stand before serving; the sugar-milk holds heat long after the dish looks cool.', 'سيبه يقف قبل التقديم؛ اللبن المحلّى بيفضل سخن حتى لما الطبق يبان بارد.', '{}');

