values ('e64dd211-47e4-5e3a-8e14-54172efedfc6', '97c7281d-8efc-50d6-a20d-25a716743ed9', 1, 'Mix the yogurt, lemon, garlic, paprika, tomato paste, oil and seasoning into a marinade.', 'اخلط الزبادي والليمون والتوم والبابريكا وصلصة الطماطم والزيت والتوابل مع بعض.', 8, null, null, '{"yogurt","lemon","garlic","paprika","tomato paste","olive oil","salt","black pepper"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('89f694cb-c667-55db-ad5c-5c1f30e7f7ec', '97c7281d-8efc-50d6-a20d-25a716743ed9', 2, 'Coat the chicken and refrigerate at least 4 hours, ideally overnight.', 'غطّي الفراخ بالتتبيلة وحطها في التلاجة ٤ ساعات على الأقل، ويفضل بالليل كله.', 10, 'Marinate in the fridge, never on the counter, and discard any marinade that touched raw chicken.', 'تبّل في التلاجة، مش على الرخامة أبدًا، وارمي أي تتبيلة لمست فراخ نية.', '{"chicken breast"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('c3de732e-3643-5890-9aaa-b8283d9b3f37', '97c7281d-8efc-50d6-a20d-25a716743ed9', 3, 'Thread onto skewers and grill hot for 12–15 minutes, turning, until charred at the edges.', 'رصّها في أسياخ واشويها على نار عالية ١٢–١٥ دقيقة مع التقليب لحد ما أطرافها تتحمّر.', 15, 'Poultry must reach 74°C / 165°F throughout. The juices should run clear.', 'الفراخ لازم توصل ٧٤°م / ١٦٥°ف في كل مكان فيها. والعصارة لازم تطلع صافية.', '{}');

