values ('436ee00d-1f6e-5e49-b9cb-ab1336bc5cca', 'f5699a73-e8c8-50f4-8426-ef429c4259c7', 2, 'Cook the vegetables with the garlic, ginger, spices and yogurt for 12 minutes.', 'اطبخ الخضار مع التوم والزنجبيل والبهارات والزبادي ١٢ دقيقة.', 12, null, null, '{"carrots","green peas","potatoes","cauliflower","garlic","ginger","curry powder","cardamom","yogurt","salt"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('c208323c-b8d7-5deb-a3c0-0fe50313e566', 'f5699a73-e8c8-50f4-8426-ef429c4259c7', 3, 'Parboil the rice for 6 minutes so it is still firm, then drain.', 'اسلق الرز ٦ دقايق عشان يفضل متماسك، وبعدين صفّيه.', 7, null, null, '{"basmati rice"}');
insert into public.recipe_steps (id, recipe_id, step_number, instruction, instruction_ar, duration_minutes, safety_note, safety_note_ar, ingredient_refs)
values ('aca947d9-64f6-5a20-8ffc-5ce4452a605e', 'f5699a73-e8c8-50f4-8426-ef429c4259c7', 4, 'Layer vegetables then rice then onions, cover tightly and steam on the lowest heat 20 minutes.', 'رصّ الخضار وبعدين الرز وبعدين البصل، غطّي كويس وبخّر على أهدى نار ٢٠ دقيقة.', 20, null, null, '{"saffron"}');

